args.content:
:root {
    --bg: #fafafa;
    --text: #222;
    --accent: #2d5a7b;
    --light-accent: #e8f0f5;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: Georgia, 'Times New Roman', serif;
    line-height: 1.7;
    color: var(--text);
    background: var(--bg);
    max-width: 700px;
    margin: 0 auto;
    padding: 2rem 1.5rem;
}

header {
    text-align: center;
    margin-bottom: 3rem;
    padding-bottom: 2rem;
    border-bottom: 1px solid #ddd;
}

h1 {
    font-size: 2.5rem;
    font-weight: normal;
    letter-spacing: 0.02em;
    color: var(--accent);
    margin-bottom: 0.5rem;
}

.tagline {
    font-style: italic;
    color: #666;
    font-size: 1.1rem;
}

h2 {
    font-size: 1.3rem;
    font-weight: normal;
    color: var(--accent);
    margin-bottom: 1rem;
    margin-top: 2.5rem;
}

section:first-of-type h2 {
    margin-top: 0;
}

p {
    margin-bottom: 1rem;
}

ul {
    margin: 1rem 0 1rem 1.5rem;
}

li {
    margin-bottom: 0.75rem;
}

a {
    color: var(--accent);
}

footer {
    margin-top: 4rem;
    padding-top: 2rem;
    border-top: 1px solid #ddd;
    text-align: center;
    font-size: 0.9rem;
    color: #888;
}
